import type { Difficulty, Question, QuestionKind, QuestionVisual } from "@/types";

type Concept = {
  p: number;
  topic: string;
  term: string;
  definition: string;
  wrong: [string, string, string];
  scenario: string;
  answer: string;
  scenarioWrong: [string, string, string];
  why: string;
  kind?: QuestionKind;
};

const table = (caption: string, rows: string[][]): QuestionVisual => ({
  type: "table",
  caption,
  headers: ["Elemento", "Evidência"],
  rows,
});

const difficulties: Difficulty[] = [
  "fácil", "fácil", "fácil", "média", "média", "média",
  "média", "média", "média", "difícil", "difícil", "difícil",
];

function buildLesson(number: number, concepts: Concept[]): Question[] {
  const lesson = `Aula ${String(number).padStart(2, "0")}`;
  const questions = concepts.flatMap((c, index): Omit<Question, "id" | "familyId" | "difficulty">[] => [
    {
      lesson, page: c.p, topic: c.topic, kind: "conceitual",
      prompt: `Qual afirmação descreve corretamente ${c.term}?`,
      options: [c.definition, ...c.wrong], correct: 0,
      explanation: c.why, source: `Design Profissional, p. ${c.p}`,
      origin: "Questão autoral baseada no material da disciplina",
    },
    {
      lesson, page: c.p, topic: c.topic, kind: c.kind ?? "prática",
      prompt: c.scenario, options: [c.answer, ...c.scenarioWrong], correct: 0,
      explanation: c.why, source: `Design Profissional, p. ${c.p}`,
      origin: "Questão autoral baseada no material da disciplina",
      visual: index < 2 ? table(`Caso para análise: ${c.topic}`, [["Contexto", c.scenario], ["Foco", c.term]]) : undefined,
    },
  ]);

  return questions.map((q, index) => ({
    ...q,
    id: `dp-${String(number).padStart(2, "0")}-${String(index + 1).padStart(2, "0")}`,
    familyId: `dp-${number}-${index + 1}`,
    difficulty: difficulties[index],
  }));
}

