const l14 = buildLesson(14, [
  { p:112, topic:"Uso estratégico", term:"IA como amplificador", definition:"Ferramenta que acelera tarefas e aprendizagem quando usada com domínio, crítica e supervisão.", wrong:["Substituto total do conhecimento.","Garantia de resposta correta.","Sistema que elimina responsabilidade humana."], scenario:"A IA gerou uma solução plausível. Qual próximo passo profissional?", answer:"Revisar, testar e confrontar a saída com requisitos e fontes.", scenarioWrong:["Publicar sem ler.","Assumir que não há erro.","Remover a autoria humana."], why:"O material enfatiza capacidades e limitações e afirma que IA amplifica, não substitui." },
  { p:113, topic:"Prompt", term:"prompt específico", definition:"Pedido com contexto, objetivo e detalhes suficientes para orientar uma resposta útil.", wrong:["Pergunta vaga sem destinatário.","Comando contraditório.","Lista de palavras sem tarefa."], scenario:"Qual prompt tende a produzir um plano mais útil?", answer:"Crie um plano de 3 meses para um júnior aprender Python para web, com projetos e 5 horas semanais.", scenarioWrong:["Como aprender Python?","Me ensine tudo.","Faça um plano bom."], why:"Contexto, foco, prazo e formato reduzem ambiguidade e tornam a resposta mais aplicável." },
  { p:114, topic:"Estrutura", term:"estrutura de prompt", definition:"Contexto, tarefa, formato e restrições organizados de forma explícita.", wrong:["Somente o nome da ferramenta.","Dados irrelevantes sem objetivo.","Pedido sem resultado esperado."], scenario:"Ao pedir revisão de currículo, qual restrição é útil?", answer:"Limite a uma página e preserve apenas experiências relacionadas à vaga.", scenarioWrong:["Responda qualquer coisa.","Não considere a vaga.","Invente resultados faltantes."], why:"Restrições e formato definem limites verificáveis para a saída." },
  { p:115, topic:"Carreira", term:"análise de vaga com IA", definition:"Comparação assistida entre requisitos da vaga e evidências reais do perfil, sob revisão humana.", wrong:["Criação de experiências inexistentes.","Candidatura automática sem leitura.","Substituição da decisão do candidato."], scenario:"Como usar IA eticamente numa vaga?", answer:"Identificar lacunas e reorganizar evidências verdadeiras para a posição.", scenarioWrong:["Inventar uma certificação.","Copiar o perfil de outro candidato.","Enviar dados confidenciais sem necessidade."], why:"IA pode apoiar análise e apresentação, mas não deve fabricar qualificações." },
  { p:116, topic:"Código", term:"copiloto de programação", definition:"Ferramenta que sugere código e explicações, exigindo revisão, testes e compreensão do desenvolvedor.", wrong:["Autoridade infalível sobre arquitetura.","Substituto de testes.","Garantia de segurança."], scenario:"Copilot sugeriu função com dependência desconhecida. O que fazer?", answer:"Entender a dependência, revisar o código e testar antes de aceitar.", scenarioWrong:["Mesclar imediatamente.","Ocultar a origem da sugestão.","Desativar todos os testes."], why:"Sugestões aceleram trabalho, mas continuam sujeitas a erro, contexto incompleto e riscos." },
  { p:117, topic:"Ferramentas", term:"escolha de ferramenta de IA", definition:"Seleção baseada na tarefa, no risco, nos dados envolvidos e na necessidade de revisão.", wrong:["Uso da mesma ferramenta para tudo.","Escolha pelo anúncio mais chamativo.","Envio irrestrito de dados sensíveis."], scenario:"Qual critério vem antes de enviar um documento profissional a uma IA?", answer:"Verificar necessidade, privacidade dos dados e política da ferramenta.", scenarioWrong:["Apenas velocidade da resposta.","Quantidade de emojis.","Popularidade nas redes."], why:"Uso estratégico inclui responsabilidade sobre dados e adequação da ferramenta à tarefa." },
]);

const l15 = buildLesson(15, [
  { p:120, topic:"Empresas", term:"profissional que resolve problemas", definition:"Pessoa que entende contexto de negócio e converte demandas em soluções tecnológicas efetivas.", wrong:["Codificador que ignora o usuário.","Pessoa que segue ferramenta sem analisar.","Especialista que evita comunicação."], scenario:"A área relata atraso, mas pede 'um sistema'. Qual primeira atitude madura?", answer:"Investigar o processo e definir o problema antes da solução.", scenarioWrong:["Escolher framework imediatamente.","Prometer automação total.","Copiar sistema de outra empresa."], why:"Empresas buscam compreensão de problemas e capacidade de traduzir demandas, não apenas código." },
  { p:121, topic:"Tendências", term:"edge computing", definition:"Processamento de dados próximo da origem para reduzir latência e apoiar dispositivos conectados.", wrong:["Armazenamento apenas em planilhas locais.","Rede social para vagas.","Método de documentação."], scenario:"Sensores precisam reagir em milissegundos sem enviar tudo a um data center distante. Qual tendência ajuda?", answer:"Edge computing.", scenarioWrong:["Somente currículo digital.","README profissional.","Scrum sem infraestrutura."], why:"Edge processa perto da fonte e aparece associado a IoT e respostas em tempo real." },
  { p:122, topic:"Vagas", term:"plataforma especializada em TI", definition:"Serviço que reúne oportunidades tecnológicas e filtros por linguagem, framework ou área.", wrong:["Comunidade sem vagas por definição.","Compilador de código.","Certificadora acadêmica."], scenario:"Qual plataforma brasileira citada é focada em vagas de tecnologia?", answer:"Programathor.", scenarioWrong:["Fscanf.","README.md.","Dockerfile."], why:"O material lista Programathor entre plataformas brasileiras especializadas." },
  { p:124, topic:"Entrevistas", term:"técnica STAR", definition:"Estrutura Situação, Tarefa, Ação e Resultado para responder perguntas comportamentais.", wrong:["Método para compilar C.","Modelo de banco de dados.","Formato de certificação."], scenario:"Ao explicar um conflito de equipe, como organizar a resposta?", answer:"Contextualizar situação e tarefa, descrever ação e apresentar resultado.", scenarioWrong:["Contar apenas o final.","Criticar colegas sem explicar a própria ação.","Inventar uma experiência."], why:"STAR torna exemplos comportamentais claros e centrados na contribuição do candidato." },
  { p:125, topic:"Fundamentos", term:"competência técnica fundamental", definition:"Base sólida em linguagens, dados, cloud, versionamento e containerização que permite aprender novas ferramentas.", wrong:["Memorização de todas as bibliotecas.","Dependência de uma única tecnologia.","Certificado sem compreensão."], scenario:"Por que dominar fundamentos ajuda diante de mudanças?", answer:"Porque conceitos transferíveis facilitam aprender novas ferramentas.", scenarioWrong:["Porque ferramentas deixam de mudar.","Porque elimina estudo contínuo.","Porque garante emprego permanente."], why:"O material prioriza bases transferíveis e domínio real de algumas tecnologias." },
  { p:127, topic:"Futuro", term:"profissional T-shaped", definition:"Pessoa com profundidade em uma área e repertório amplo para colaborar com outras disciplinas.", wrong:["Generalista sem profundidade.","Especialista incapaz de conversar com outras áreas.","Profissional que troca de área diariamente."], scenario:"Uma dev domina React e compreende UX, dados e produto o bastante para colaborar. Que perfil demonstra?", answer:"T-shaped.", scenarioWrong:["Especialização isolada.","Perfil sem foco.","Carreira sem aprendizagem."], why:"T-shaped combina especialização profunda com visão interdisciplinar e aparece como tendência de futuro." },
]);

